effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat12;
bvec2 u_xlatb12;
float u_xlat13;
float u_xlat19;
bool u_xlatb19;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat12.xy = _center.xy + vec2(-0.5, -0.5);
    u_xlat1.x = _angle * 0.0174532942;
    u_xlat1.y = cos(u_xlat1.x);
    u_xlat1.x = sin((-u_xlat1.x));
    u_xlat2 = u_xlat1.yyxx * vec4(-0.5, 0.5, -0.5, 0.5);
    u_xlat1 = u_xlat12.xyxy * vec4(_viewport_ratio.x, _viewport_ratio.y, _viewport_ratio.x, _viewport_ratio.y) + u_xlat2.xzyw;
    u_xlat0.xy = u_xlat0.xy * vec2(_viewport_ratio.x, _viewport_ratio.y) + (-u_xlat1.xy);
    u_xlat12.xy = (-u_xlat1.xy) + u_xlat1.zw;
    u_xlat13 = dot(u_xlat0.xy, u_xlat12.xy);
    u_xlat19 = dot(u_xlat12.xy, u_xlat12.xy);
    u_xlat13 = u_xlat13 / u_xlat19;
    u_xlat0.xy = (-vec2(u_xlat13)) * u_xlat12.xy + u_xlat0.xy;
    u_xlat19 = u_xlat0.x * u_xlat12.y;
    u_xlat19 = u_xlat12.x * u_xlat0.y + (-u_xlat19);
    u_xlatb19 = 0.0<u_xlat19;
    u_xlat2.x = dot(u_xlat0.xy, u_xlat0.xy);
    u_xlat2.x = sqrt(u_xlat2.x);
    u_xlat2.x = (-u_xlat2.x) * _strength;
    u_xlat2.x = u_xlat2.x * 28.8539009;
    u_xlat2.x = exp2(u_xlat2.x);
    u_xlat19 = (u_xlatb19) ? u_xlat2.x : 1.0;
    u_xlat12.xy = vec2(u_xlat13) * u_xlat12.xy + u_xlat1.xy;
    u_xlat0.xy = u_xlat0.xy * vec2(u_xlat19) + u_xlat12.xy;
    u_xlat0.xy = u_xlat0.xy / vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat0.xy = u_xlat0.xy + vec2(0.5, 0.5);
    u_xlatb12.xy = lessThan(u_xlat0.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb1.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
    u_xlatb12.x = u_xlatb12.x || u_xlatb1.x;
    u_xlatb12.x = u_xlatb12.y || u_xlatb12.x;
    u_xlatb12.x = u_xlatb1.y || u_xlatb12.x;
    u_xlat1 = texture(inputImg, u_xlat0.xy);
    u_xlat0.x = (u_xlatb12.x) ? 0.0 : 1.0;
    u_xlat0 = u_xlat0.xxxx * u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
